class Solution:
    def minOperationsMaxProfit(self, customers: List[int], boardingCost: int, runningCost: int) -> int:
        wait = profit = best = 0
        ans, rot, i, n = -1, 0, 0, len(customers)
        while wait > 0 or i < n:
            if i < n:
                wait += customers[i]
                i += 1
            board = min(4, wait)
            wait -= board
            rot += 1
            profit += board * boardingCost - runningCost
            if profit > best:
                best = profit
                ans = rot
        return ans

