    def minOperationsMaxProfit(self, customers: List[int], boardingCost: int, runningCost: int) -> int:
        B, R = boardingCost, runningCost
        wait = profit = 0
        best, ans = 0, -1
        for rot, c in enumerate(customers, 1):
            wait += c
            board = min(4, wait)
            wait -= board
            profit += board * B - R
            if profit > best:
                best, ans = profit, rot
        t0, p0 = len(customers), profit
        f, rem = divmod(wait, 4)
        unit = 4 * B - R
        if unit > 0 and f:
            if p0 + f * unit > best:
                best, ans = p0 + f * unit, t0 + f
            p0 += f * unit
        if rem:
            if p0 + rem * B - R > best:
                ans = t0 + f + 1
        return ans

