class Solution {
public:
    int minOperationsMaxProfit(vector<int>& customers, int boardingCost, int runningCost) {
        long long B = boardingCost, R = runningCost;
        int wait = 0, n = customers.size();
        long long profit = 0, best = 0;
        int ans = -1;
        for (int rot = 1; rot <= n; ++rot) {
            wait += customers[rot - 1];
            int board = min(4, wait);
            wait -= board;
            profit += board * B - R;
            if (profit > best) { best = profit; ans = rot; }
        }
        int t0 = n, f = wait / 4, rem = wait % 4;
        long long unit = 4 * B - R, p0 = profit;
        if (unit > 0 && f > 0) {
            if (p0 + f * unit > best) { best = p0 + f * unit; ans = t0 + f; }
            p0 += f * unit;
        }
        if (rem > 0 && p0 + rem * B - R > best) {
            ans = t0 + f + 1;
        }
        return ans;
    }
};

